DAL -->\n  <div class=\"modal-overlay\" id=\"loginModal\" data-close-overlay>\n    <div class=\"modal\">\n      <button type=\"button\" class=\"modal-close\" data-close>&times;</button>\n      <div class=\"modal-logo\"><span style=\"font:800 60% 'Plus Jakarta Sans',sans-serif;color:#0A2E6B\">K</span></div>\n      <span class=\"preview-note\">UI PREVIEW ONLY \u2014 NO REAL AUTH</span>\n      <h3>Ku soo dhawoow</h3>\n      <p class=\"sub\">Dooro sidee aad u gelayso Kobciye</p>\n      <div class=\"role-grid\">\n        <button type=\"button\" class=\"role-btn active\" data-role=\"school\"><span>\ud83c\udfeb</span>Dugsiga</button>\n        <button type=\"button\" class=\"role-btn\" data-role=\"waalid\"><span>\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc67</span>Waalid</button>\n        <button type=\"button\" class=\"role-btn\" data-role=\"arday\"><span>\ud83c\udf93</span>Arday</button>\n        <button type=\"button\" class=\"role-btn\" data-role=\"super\"><span>\ud83d\udee1\ufe0f</span>Super Admin</button>\n      </div>\n      <div class=\"modal-body\">\n        <!-- school admin / super admin: email + password -->\n        <div class=\"role-extra show\" data-role-extra=\"school,super\">\n          <label>Email</label>\n          <input type=\"email\" placeholder=\"dugsiga@kobciye.com\">\n          <label>Password</label>\n          <input type=\"password\" placeholder=\"Samee password adag\">\n        </div>\n\n        <!-- parent: only the info needed from a parent -->\n        <div class=\"role-extra\" data-role-extra=\"waalid\">\n          <label>Numberka Mobile</label>\n          <input type=\"tel\" placeholder=\"Numberka dugsiga ku diiwaan gashan\">\n          <label>Code-ka Maamulaha</label>\n          <input placeholder=\"Code-ka dugsigu ku siiyay\">\n          <div class=\"kids-head\"><strong>Carruurtaada</strong><button type=\"button\" class=\"btn-addkid\" id=\"addChild\">+ Ku dar ilmo</button></div>\n          <div id=\"childList\">\n            <input data-cf=\"name\" placeholder=\"Magaca ilmaha\" style=\"margin-bottom:10px\">\n          </div>\n        </div>\n\n        <!-- student: only the info needed from a student -->\n        <div class=\"role-extra\" data-role-extra=\"arday\">\n          <label>Magaca oo dhamaystiran</label>\n          <input placeholder=\"Magacaaga buuxa\">\n          <label>Fasalka</label>\n          <input placeholder=\"Tusaale: Form 5A\">\n        </div>\n\n        <a class=\"btn-submit\" data-login-go href=\"#\">Ku Soo Gal &rarr;</a>\n        <p class=\"alt\">Ma leedahay akoon? <a data-register>Diiwaan Gali</a></p>\n        <p class=\"alt small\"><a data-forgot>Kabixinnaa password-ka</a></p>\n      </div>\n    </div>\n  </div>\n\n  <!-- FORGOT MODAL -->\n  <div class=\"modal-overlay\" id=\"forgotModal\" data-close-overlay>\n    <div class=\"modal narrow\">\n      <button type=\"button\" class=\"modal-close\" data-close>&times;</button>\n      <div data-forgot-pending>\n        <div class=\"fp-icon\">&#128273;</div>\n        <h3>Password-ka soo celi</h3>\n        <p class=\"sub\">Geli email-ka akoonkaaga. Waxaan kuu soo dirnaa tilmaamo aad password cusub ku samaysid.</p>\n        <label>Email</label>\n        <input type=\"email\" placeholder=\"magaca@kobciye.com\">\n        <a class=\"btn-submit\" id=\"sendReset\" href=\"#\">Ii soo dir link-ga &rarr;</a>\n        <p class=\"alt\">Waad xusuusatay? <a data-back-login>Dib ugu noqo</a></p>\n      </div>\n      <div data-forgot-sent style=\"display:none\">\n        <div class=\"fp-sent-ic\">&#10003;</div>\n        <h3 style=\"text-align:center\">Email-ka waa la diray!</h3>\n        <p class=\"sub\" style=\"text-align:center\">Fadlan hubi sanduuqaaga email-ka oo raac tilmaamaha si aad password cusub u samaysid.</p>\n        <a class=\"btn-submit\" data-back-login href=\"#\">Dib ugu noqo Login</a>\n      </div>\n    </div>\n  </div>\n\n  <!-- REGISTER MODAL -->\n  <div class=\"modal-overlay\" id=\"registerModal\" data-close-overlay>\n    <div class=\"modal wide\">\n      <button type=\"button\" class=\"modal-close\" data-close>&times;</button>\n      <span class=\"preview-note\">UI PREVIEW ONLY \u2014 NO REAL AUTH</span>\n      <h3>Diiwaan geli Dugsigaaga</h3>\n      <p class=\"sub\">Buuxi macluumaadka dugsiga si aad u bilowdo bishaada bilaashka ah.</p>\n      <label class=\"logo-upload\">\n        <span class=\"box\" id=\"logoBox\">\ud83d\udcf7</span>\n        <span><strong>Logo-ga Dugsiga</strong><small>Riix si aad u soo geliso sawirka logo-ga</small></span>\n        <input type=\"file\" accept=\"image/*\" id=\"logoInput\" style=\"display:none\">\n      </label>\n      <div class=\"grid2\">\n        <div class=\"full\"><label>Magaca Dugsiga</label><input placeholder=\"Tusaale: Dugsiga Hidaayada\"></div>\n        <div><label>Nooca Dugsiga</label><select><option>Dugsi Hoose</option><option>Dugsi Sare</option><option>Labadaba</option></select></div>\n        <div><label>Magaalada</label><input placeholder=\"Gabiley\"></div>\n        <div><label>Telefoon</label><input placeholder=\"+252 63 0000000\"></div>\n        <div><label>Email</label><input type=\"email\" placeholder=\"dugsi@kobciye.com\"></div>\n        <div><label>Magaca Maamulaha</label><input placeholder=\"Magaca buuxa\"></div>\n        <div><label>Tirada Ardayda</label><input type=\"number\" placeholder=\"Tusaale: 267\"></div>\n        <div class=\"full\"><label>Password</label><input type=\"password\" placeholder=\"Samee password ammaan ah\"></div>\n      </div>\n      <a class=\"btn-submit\" data-login-go href=\"#\" style=\"margin-top:20px\">Diiwaan geli Dugsiga &rarr;</a>\n      <p class=\"alt\">Akoon hore ma leedahay? <a data-login>Gal akoonka</a></p>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  window.addEventListener('load', function () {\n    var loader = document.getElementById('kobLoader');\n    if (!loader) return;\n    setTimeout(function () { loader.classList.add('is-hidden'); }, 350);\n  });\n</script>\n\n<script>\n(function(){\n  function enter(){ try{ window.parent.postMessage('kobciye:enter','*'); }catch(e){} }\n  document.addEventListener('click', function(e){\n    var t = e.target.closest('[data-login], .btn-primary, .header-cta, .hero-ctas a, .hero-ctas button, .plan-cta, [data-go]');\n    if(t){ e.preventDefault(); enter(); }\n  });\n  // hide the loader the page shows on its own\n  var L=document.getElementById('kobLoader'); if(L){ setTimeout(function(){L.style.display='none';},300); }\n})();\n</script>\n\n</body>\n</html>\n";
